162	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
163		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
164		if !ok {
165			return store.ErrNotFound
166		}
167		if sub.CancelAtPeriodEnd {
168			end := sub.CurrentPeriodEnd
169			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
170				x.Status, x.CanceledAt = store.Canceled, &end
171				return nil
172			})
173			if err == nil {
174				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
175			}
176			return err
177		}
178		start := now
179		end := billing.AddInterval(start, plan.Interval)
180		paid := true
181		var err error
182		switch {
183		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
184			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
185		case plan.UsageType == store.Licensed:
186			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
187		}
188		if err != nil {
189			return err
190		}
191		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
192			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
193			if paid {
194				x.Status = store.Active
195			} else {
196				x.Status = store.PastDue
197			}
198			return nil
199		})
200		if err != nil {
201			return err
202		}
203		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
204		return nil
205	}
206	
207	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
208	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
209	// payment method stays open and counts as paid here (it is paid by hand). A metered period without usage has nothing to
210	// invoice, so it creates no invoice.
211	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
212		var lines []store.Line
213		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
214		switch plan.UsageType {
215		case store.Licensed:
216			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
217		case store.Metered:
218			used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end)
219			if used == 0 {
220				return true, nil
221			}
222			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
223		}
224		ps, pe := start, end
225		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
226			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
227		if err != nil {
228			return false, err
229		}
230		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
231		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
232		var decline *payments.DeclineError
233		switch {
234		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
235			return true, nil
236		case errors.As(err, &decline):
237			return false, nil
238		default:
239			return false, err
240		}
241	}
