62	// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
63	// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
64	// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
65	// error wraps ErrUnavailable.
66	func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
67		inv, ok := s.Store.Invoice(orgID, invoiceID)
68		if !ok {
69			return store.Invoice{}, store.Payment{}, store.ErrNotFound
70		}
71		switch inv.Status {
72		case store.InvoicePaid:
73			return inv, store.Payment{}, ErrAlreadyPaid
74		case store.InvoiceVoid:
75			return inv, store.Payment{}, ErrInvoiceVoid
76		}
77		total := billing.Compute(inv).Total
78		if total <= 0 {
79			inv, err := s.markPaid(ctx, inv, store.Payment{})
80			return inv, store.Payment{}, err
81		}
82		if paymentMethod == "" {
83			if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
84				paymentMethod = c.DefaultPaymentMethod
85			}
86		}
87		if paymentMethod == "" {
88			return inv, store.Payment{}, ErrNoPaymentMethod
89		}
90		res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
91		var decline *DeclineError
92		switch {
93		case errors.As(err, &decline):
94			p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
95			if perr != nil {
96				return inv, store.Payment{}, perr
97			}
98			s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
99			return inv, p, err
100		case err != nil:
101			if errors.Is(err, ErrUnavailable) {
102				return inv, store.Payment{}, err
103			}
104			return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
105		}
106		p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
107		if err != nil {
108			return inv, store.Payment{}, err
109		}
110		inv, err = s.markPaid(ctx, inv, p)
111		return inv, p, err
112	}
